  for ref,parts in anchors.items():
   for part in parts:self.assertIn(part,cases[ref.replace(':','-')]['analysis'])
  self.assertIn('not all of they kjv_gospel obey:perf',cases['10-16']['analysis'])
  self.assertIn('i say:pr',cases['10-19']['analysis'])
  self.assertIn('ipl you:a',cases['10-19']['analysis'])
  self.assertIn('to god against kjv_israel kjv_intercede_against_romans',cases['11-2']['analysis'])
  self.assertIn('four+twelve+twelve+twelve and seven+twelve and four',cases['11-4']['analysis'])
  self.assertIn('otherwise work no more work',cases['11-6']['analysis'])
  self.assertIn('kjv_blindness in part',cases['11-25']['analysis'])
  self.assertIn('without kjv_repentance_reconsider_romans',cases['11-29']['analysis'])
  self.assertIn('wesg many be:cv one_num body',cases['12-5']['analysis'])
  self.assertIn('not all kjv_member_body_romans:pl same kjv_office_function_romans',cases['12-4']['analysis'])
  self.assertIn('kjv_charcoal:pl of fire upon his/head',cases['12-20']['analysis'])
